    "current_state": {
      "scene_count": 3,
      "relationship": "久未联系，未自动和解",
      "location": "暴雨夜",
      "prop": "黄铜钥匙 A-17，身份与 custody 可追踪",
      "knowledge": "母亲留下钥匙和储物间共同开启用途未揭示",
      "visual_state": {
        "scene_1": "暴雨夜，许宁湿透制服",
        "scene_2": "换下湿制服，场景二",
        "scene_3": "干衣，暴雨渐歇"
